const https = require('https');

// Keep this secure or move to Key Store
const connectionString = "postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

// Helper function to send HTTP requests to Neon
async function executeQuery(query, params = []) {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify({ query, params });

        const options = {
            hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',
            port: 443,
            path: '/sql',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Neon-Connection-String': connectionString,
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = https.request(options, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    try {
                        const parsed = JSON.parse(data);
                        // Handle both array and object responses based on Neon API versions
                        resolve(Array.isArray(parsed) ? parsed : parsed.rows || []);
                    } catch (e) {
                        reject(new Error("Failed to parse Neon JSON response"));
                    }
                } else {
                    reject(new Error(`Neon API Error: ${res.statusCode} - ${data}`));
                }
            });
        });

        req.on('error', reject);
        req.write(postData);
        req.end();
    });
}

async function getSQLPrompt() {
    let sqlSchemaPrompt = '';

    try {
        // 1. Get all user-defined tables
        const tablesResult = await executeQuery(`
            SELECT table_name 
            FROM information_schema.tables 
            WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
        `);

        for (const tableRow of tablesResult) {
            const tableName = tableRow.table_name;

            // 2. Get column definitions for each table
            const schemaInfo = await executeQuery(`
                SELECT column_name, data_type, is_nullable 
                FROM information_schema.columns 
                WHERE table_name = $1
            `, [tableName]);

            const createColumns = [];
            const columnNames = [];

            for (const column of schemaInfo) {
                const name = column.column_name;
                const type = column.data_type.toUpperCase();
                const notNull = column.is_nullable === 'NO' ? 'NOT NULL' : '';
                columnNames.push(name);
                createColumns.push(`${name} ${type} ${notNull}`.trim());
            }

            const sqlCreateTableQuery = `CREATE TABLE ${tableName} (${createColumns.join(', ')});`;
            const sqlSelectTableQuery = `SELECT * FROM ${tableName} LIMIT 3;`;
            let allValues = [];

            // 3. Fetch sample rows to give the LLM data context
            try {
                const rows = await executeQuery(sqlSelectTableQuery);
                allValues = rows.map(row => 
                    columnNames.map(col => {
                        return row[col] === null ? 'NULL' : String(row[col]);
                    }).join(' | ')
                );
            } catch (err) {
                allValues.push('[ERROR FETCHING SAMPLE ROWS]');
            }

            // Append formatted table schema to the final prompt
            sqlSchemaPrompt += sqlCreateTableQuery + '\n' + 
                               sqlSelectTableQuery + '\n' + 
                               columnNames.join(' | ') + '\n' + 
                               allValues.join('\n') + '\n\n';
        }

        return sqlSchemaPrompt;

    } catch (err) {
        console.error(err);
        return `Error generating schema: ${err.message}`;
    }
}

// Execute and return the generated schema text to the flow state
return await getSQLPrompt();

