const https = require('https');

// The SQL query injected from your flow state variables
const sqlQuery = typeof $sqlQuery !== 'undefined' ? $sqlQuery : '';

// Your Neon connection string (Highly recommend moving to Key Store eventually!)
const connectionString = "postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

async function runSQLQuery(query) {
    return new Promise((resolve) => {
        if (!query) {
            return resolve("[Error executing query]: No SQL query provided.");
        }

        const postData = JSON.stringify({ query: query, params: [] });

        const options = {
            hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',
            port: 443,
            path: '/sql',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Neon-Connection-String': connectionString,
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = https.request(options, (res) => {
            let data = '';

            // Accumulate response chunks
            res.on('data', chunk => data += chunk);

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    try {
                        const parsedData = JSON.parse(data);
                        // Safely extract rows depending on Neon API response format
                        const rows = Array.isArray(parsedData) ? parsedData : parsedData.rows || [];

                        if (rows.length === 0) {
                            resolve('[No results returned]');
                        } else {
                            // Format results so the LLM can read them cleanly
                            const columnNames = Object.keys(rows[0]);
                            const header = columnNames.join(' | ');

                            // Map through rows, handle nulls gracefully, and join with pipes
                            const values = rows.map(row => 
                                columnNames.map(col => row[col] === null ? 'NULL' : String(row[col])).join(' | ')
                            );

                            const formattedResult = query + '\n' + header + '\n' + values.join('\n');
                            resolve(formattedResult);
                        }
                    } catch (e) {
                        resolve(`[Error parsing response]: ${e.message}`);
                    }
                } else {
                    // This captures SQL syntax errors returned by the Neon DB
                    resolve(`[Error executing query]: ${data}`);
                }
            });
        });

        // Handle network-level errors
        req.on('error', (e) => {
            resolve(`[Error executing query]: HTTPS Request failed - ${e.message}`);
        });

        req.write(postData);
        req.end();
    });
}

// Execute and return the formatted result to the flow state
return await runSQLQuery(sqlQuery);

